from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class ApucchTddParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        cell_ent = self.enb_ent_config['cells'][self.cell_num]

        if execution_config['is_fsm5']:
            self.set_parameter('actLbPucchReg', 'true')
            self.set_parameter('aPucchSrPeriodUpperLimit', 40)
            self.set_parameter('aPucchMinNumEmergencySessions', 10)

        if cell_ent['dl_mimo_mode'] == 'Closed Loop MIMO (4x4)':
            self.set_parameter('aPucchSrPeriodUpperLimit', 40)
